<template><div class="app-container"><el-alert type="info" :closable="false" title="已报产值为已提交/已月度确认的每日填报；项目估值不等于实际收入，未报价不按零计算。进度为当前累计已确认工作量。"/>
<el-form inline class="filter"><el-form-item label="报表"><el-select v-model="kind" @change="page=1;load()" style="width:240px"><el-option v-for="k in options.kinds||[]" :key="k.key" :label="k.label" :value="k.key"/></el-select></el-form-item><el-form-item label="企业"><el-select v-model="companyId" @change="page=1;load()"><el-option v-if="options.allCompanies" label="平台全部企业" :value="0"/><el-option v-for="c in options.companies||[]" :key="c.id" :label="c.company_name" :value="c.id"/></el-select></el-form-item><el-form-item label="日期区间"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="趋势粒度"><el-select v-model="group" style="width:100px"><el-option label="按日" value="DAY"/><el-option label="按月" value="MONTH"/></el-select></el-form-item><el-button type="primary" @click="page=1;load()">查询</el-button><el-button v-if="options.canExport" :loading="exporting" @click="exportExcel">导出Excel</el-button><el-button v-if="options.canPrice" @click="openPrices">任务报价</el-button></el-form>
<el-alert v-if="kind==='reconciliation'" title="按所选完整自然月核对：差额为当前已报产值与上次月度核对快照之差，不是银行到账或付款差额；无快照显示空白。" :closable="false" type="warning"/>
<el-alert v-if="kind==='personnel'" title="人员表为当前档案；日期仅用于本次入职/离职日的期间计数，不还原历史某日的在职人数。" :closable="false" type="info"/>
<div class="metrics"><el-card v-for="(value,key) in report.summary||{}" :key="key" shadow="hover"><div class="metric-label">{{labels[key]||key}}</div><strong>{{value}}</strong></el-card></div>
<el-card class="chart-box" shadow="never"><div ref="chartRef" style="height:340px;width:100%"></div></el-card>
<el-table :data="report.rows||[]" v-loading="loading" border><el-table-column v-for="column in columns" :key="column" :prop="column" :label="labels[column]||column" min-width="150" show-overflow-tooltip><template #default="{row}">{{display(row[column],column)}}</template></el-table-column><el-table-column v-if="kind==='estimates'" label="报价快照" width="180"><template #default="{row}"><el-button v-if="options.canPrice&&!options.allCompanies&&row.status==='ACTIVE'" link type="primary" @click="snapshot(row)">补录缺失快照</el-button><el-button link @click="viewQuotes(row)">报价明细</el-button></template></el-table-column></el-table><pagination v-show="report.total>0" :total="report.total||0" v-model:page="page" v-model:limit="size" @pagination="load"/>
<el-dialog v-model="pricesVisible" title="任务发布方维护单位报价" width="850px"><el-alert type="warning" :closable="false" title="报价只用于估算。新关联项目保存快照；已有快照不自动覆盖。执行中未报价项目可由企业管理者补录，完成/归档项目不回填。"/><el-table :data="priceTasks"><el-table-column prop="title" label="任务"/><el-table-column prop="unit" label="工作量单位"/><el-table-column label="单价（元/单位）"><template #default="{row}">{{row.unit_price===null?'未报价':row.unit_price}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="!['COMPLETED','ARCHIVED'].includes(row.status)" link @click="editPrice(row)">维护报价</el-button></template></el-table-column></el-table></el-dialog>
<el-dialog v-model="priceVisible" title="单位报价" width="500px"><el-form label-width="100px"><el-form-item label="单价（元）"><el-input v-model="priceForm.unitPrice" placeholder="非负金额，最多四位小数"/></el-form-item><el-form-item label="报价说明"><el-input v-model="priceForm.opinion" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="savePrice">保存报价</el-button></template></el-dialog>
<el-dialog v-model="quotesVisible" title="项目报价快照明细" width="900px"><el-table :data="quoteLines"><el-table-column v-for="key in ['taskTitle','plannedQuantity','confirmedQuantity','unit','unitPrice','plannedEstimate','confirmedEstimate','priceVersion','priceSnapshotTime']" :key="key" :prop="key" :label="labels[key]||key" min-width="140"><template #default="{row}">{{display(row[key],key)}}</template></el-table-column></el-table></el-dialog>
</div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import * as echarts from 'echarts'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const options=ref({}),kind=ref(''),companyId=ref(0),range=ref([]),group=ref('DAY'),page=ref(1),size=ref(20),report=ref({}),loading=ref(false),exporting=ref(false),saving=ref(false),chartRef=ref(),pricesVisible=ref(false),priceVisible=ref(false),priceTasks=ref([]),priceForm=ref({}),quotesVisible=ref(false),quoteLines=ref([])
let chart,sequence=0
const labels={id:'编号',company_id:'企业编号',company_name:'企业名称',credit_code:'信用代码',user_id:'账号编号',employee_no:'工号',real_name:'姓名',contact_phone:'电话',job_title:'岗位',status:'状态',entry_date:'本次入职日',leave_date:'本次离职日',project_code:'项目编号',project_name:'项目名称',unit:'单位',output_date:'业务日期',output_value:'填报产值（元）',remark:'备注',period:'日期/月',reported:'已报产值（元）',confirmed:'其中已确认（元）',companyCount:'企业数',activeCompanyCount:'有效企业数',employeeCount:'去重员工人数',activeEmployeeCount:'在职人数',projectCount:'项目数',monthReportedValue:'本月已报产值（元）',reportedValue:'期间已报产值（元）',confirmedValue:'其中已月度确认（元）',submittedValue:'提交待月度确认（元）',draftValue:'草稿金额（元）',returnedValue:'退回金额（元）',recordCount:'记录数',missingDays:'期间应报日漏报数',profileCount:'档案数',distinctUserCount:'去重人数',activeProfiles:'在职档案数',leftProfiles:'离职档案数',currentEntryInPeriod:'本次入职日在期间',currentLeaveInPeriod:'本次离职日在期间',totalQuantity:'目标工作量',confirmedQuantity:'累计已确认工作量',periodConfirmedQuantity:'期间已确认工作量',remainingQuantity:'剩余工作量',percent:'当前进度（%）',plannedEstimate:'计划估值（元）',confirmedEstimate:'确认量折算估值（元）',periodConfirmedEstimate:'期间确认量折算估值（元）',pricedPlannedSubtotal:'已报价部分计划估值（元）',pricedTaskCount:'已报价任务数',unpricedTaskCount:'未报价任务数',completedProjects:'完成/归档项目数',unpricedProjects:'未全额报价项目数',projectId:'项目编号',projectName:'项目名称',taskId:'任务编号',taskTitle:'任务名称',plannedQuantity:'计划量',unitPrice:'单价（元/单位）',priceVersion:'报价版本',priceSnapshotTime:'快照时间',reportMonth:'核对月份',snapshotValue:'核对快照（元）',difference:'已报与快照差额（元）',snapshotAction:'上次核对结果',snapshotTime:'快照时间',checkStatus:'月度核对状态',rows:'核对行数',confirmedMonths:'已确认企业月份数',snapshotMissing:'无快照月份数',datasets:'数据集数',dataset:'数据集',create_time:'创建时间'}
const states={ACTIVE:'在职/执行中',LEFT:'离职',DRAFT:'草稿',SUBMITTED:'已提交',CONFIRMED:'已确认',RETURNED:'已退回',COMPLETED:'已完成',ARCHIVED:'已归档',OPEN:'待核对',UNREVIEWED:'尚未核对',DISABLED:'停用'}
const columns=computed(()=>{const keys=new Set();for(const row of report.value.rows||[])for(const key of Object.keys(row))if(!Array.isArray(row[key])&&typeof row[key]!=='object'||row[key]===null)keys.add(key);return [...keys].filter(k=>k!=='quoteLines')})
function display(value,key){if(value===null||value===undefined)return ['unitPrice','plannedEstimate','confirmedEstimate','periodConfirmedEstimate'].includes(key)?'未报价':'—';return states[value]||value}
function params(){return {kind:kind.value,companyId:companyId.value||undefined,from:range.value?.[0],to:range.value?.[1],group:group.value}}
async function load(){if(!kind.value)return;const id=++sequence;loading.value=true;try{const r=await request({url:'/statistics/report',params:{...params(),pageNum:page.value,pageSize:size.value}});if(id===sequence){report.value=r.data;await nextTick();draw()}}finally{if(id===sequence)loading.value=false}}
function draw(){if(!chartRef.value)return;if(!chart)chart=echarts.init(chartRef.value);const styles=getComputedStyle(chartRef.value),chartText=styles.getPropertyValue('--el-text-color-primary').trim()||'#303133',chartLine=styles.getPropertyValue('--el-border-color-light').trim()||'#e4e7ed';const data=report.value;if(data.trend){chart.setOption({textStyle:{color:chartText},title:{textStyle:{color:chartText},text:'企业产值趋势（元）'},tooltip:{trigger:'axis'},legend:{top:30,textStyle:{color:chartText}},grid:{top:75,left:70,right:25,bottom:45},xAxis:{type:'category',axisLabel:{color:chartText},axisLine:{lineStyle:{color:chartLine}},data:data.trend.map(r=>r.period)},yAxis:{type:'value',axisLabel:{color:chartText},splitLine:{lineStyle:{color:chartLine}}},series:[{name:'已报产值',type:'line',data:data.trend.map(r=>Number(r.reported))},{name:'其中已确认',type:'line',data:data.trend.map(r=>Number(r.confirmed))}]},true)}else if(kind.value==='personnel'){chart.setOption({textStyle:{color:chartText},title:{textStyle:{color:chartText},text:'当前人员档案状态'},tooltip:{trigger:'item'},series:[{type:'pie',radius:['35%','65%'],data:[{name:'在职',value:data.summary?.activeProfiles||0},{name:'离职',value:data.summary?.leftProfiles||0}]}]},true)}else{const rows=(data.rows||[]).slice(0,20);const finance=kind.value==='reconciliation';chart.setOption({textStyle:{color:chartText},title:{textStyle:{color:chartText},text:finance?'月度已报与核对快照（元）':kind.value==='full'?'各业务数据集记录数':'当前项目进度（%，本页前20项）'},tooltip:{trigger:'axis'},grid:{top:50,left:70,right:25,bottom:75},xAxis:{type:'category',axisLabel:{color:chartText},axisLine:{lineStyle:{color:chartLine}},data:rows.map(r=>r.project_name||r.reportMonth||r.dataset),axisLabel:{rotate:20,color:chartText}},yAxis:{type:'value',axisLabel:{color:chartText},splitLine:{lineStyle:{color:chartLine}},max:finance||kind.value==='full'?undefined:100},series:[{name:finance?'已报产值':kind.value==='full'?'记录数':'进度',type:'bar',data:rows.map(r=>Number(finance?r.reportedValue:kind.value==='full'?r.recordCount:r.percent))},...(finance?[{name:'核对快照',type:'bar',data:rows.map(r=>r.snapshotValue===null?null:Number(r.snapshotValue))}]:[])]},true)}}
function resize(){chart?.resize()}
async function exportExcel(){exporting.value=true;try{const blob=await request({url:'/statistics/export',params:params(),responseType:'blob'});if(blob.type.includes('json')){const e=JSON.parse(await blob.text());ElMessage.error(e.msg||'导出失败');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${options.value.kinds.find(k=>k.key===kind.value)?.label||'统计报表'}.xlsx`;a.click();URL.revokeObjectURL(url)}finally{exporting.value=false}}
async function openPrices(){priceTasks.value=(await request({url:'/statistics/price-tasks'})).data;pricesVisible.value=true}
function editPrice(row){priceForm.value={id:row.id,unitPrice:row.unit_price===null?'':String(row.unit_price),version:row.price_version,opinion:''};priceVisible.value=true}
async function savePrice(){if(!/^(0|[1-9]\d{0,13})(\.\d{1,4})?$/.test(priceForm.value.unitPrice)||!priceForm.value.opinion?.trim()){ElMessage.warning('请填写非负单价（最多四位小数）和说明');return}saving.value=true;try{await request({url:'/statistics/prices/'+priceForm.value.id,method:'put',data:priceForm.value});priceVisible.value=false;await openPrices();await load();ElMessage.success('报价已保存，已有项目快照不会自动覆盖')}finally{saving.value=false}}
async function snapshot(row){const r=await ElMessageBox.prompt('仅补录缺失报价，不覆盖已有快照；请输入原因','补录项目报价快照',{inputPattern:/\S+/,inputErrorMessage:'原因必填'});const result=await request({url:`/statistics/projects/${row.id}/price-snapshot`,method:'post',data:{opinion:r.value}});ElMessage.success(`已补录 ${result.data} 条报价快照`);await load()}
function viewQuotes(row){quoteLines.value=row.quoteLines||[];quotesVisible.value=true}
onMounted(async()=>{options.value=(await request({url:'/statistics/options'})).data;kind.value=options.value.kinds[0]?.key;companyId.value=options.value.allCompanies?0:options.value.companies[0]?.id;await load();window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart?.dispose();chart=null})
</script>
<style scoped>.filter{margin-top:18px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin:18px 0}.metric-label{color:var(--el-text-color-regular);font-size:13px;margin-bottom:10px}.metrics strong{font-size:23px;color:var(--el-color-primary);overflow-wrap:anywhere}.chart-box{margin-bottom:20px}</style>
